--################
--## AUTOSTART ###
--################
-- Port fidèle du spawn-at-startup de Niri (config.kdl)

-- Shell Catalyst (Quickshell) — remplace waybar
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

-- Dock

-- Polkit (absent de niri mais nécessaire sous Hyprland)

-- Applets & services

-- Fond d'écran (gère awww/swww/mpvpaper + matugen)

-- Idle / lock

-- Cliphist (clipboard history)

-- Publie l'environnement de la session dans systemd (services user : sekaipop-rs…)

-- Workspaces dynamiques : pas de daemon, Hyprland détruit nativement les
-- workspaces vides. dyn-ws.sh fournit la navigation (voir keybinds.conf).

-- Remarques :
-- - swaync n'est pas lancé : Catalyst possède les notifications (replaceWaybar)
-- - sekaipop-rs est géré par son unité systemd user (active)

hl.on("hyprland.start", function()
    hl.exec_cmd(catalyst .. "/catalyst-session.sh")
    hl.exec_cmd("$HOME/.config/dock/launch.sh")
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("/usr/bin/netbird-ui --daemon-addr unix:///var/run/netbird/main.sock")
    hl.exec_cmd(niriScripts .. "/wallpaper.sh restore && sleep 1 && " .. catalyst .. "/catalyst-walls.sh restore")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE HYPRLAND_INSTANCE_SIGNATURE")
end)

